  [Fact] public async Task Full_invoice_cove_reconciliation_matches_all_supported_header_fields(){await using var f=await Fixture.Create();var profile=await f.Profile("RECON-INV-COVE-V1","COMMERCIAL_INVOICE","COVE_ACK",HeaderFields());var left=await f.Document("COMMERCIAL_INVOICE",HeaderValues());var right=await f.Document("COVE_ACK",HeaderValues());var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));Assert.Equal(ReconciliationOutcome.MATCH,result.Outcome);Assert.Equal(8,result.ComparableFieldCount);Assert.Equal(8,result.MatchCount);Assert.Equal(100m,result.CoveragePercent);Assert.All(result.FieldResults,x=>Assert.Equal(CrossValidationOutcome.MATCH,x.Outcome));Assert.Equal(left.Id,result.LeftDocumentId);Assert.Equal(right.Id,result.RightDocumentId);Assert.Equal(profile.Id,result.ProfileId);}

  [Fact] public async Task One_total_difference_produces_exactly_one_mismatch_and_difference_100(){await using var f=await Fixture.Create();await f.Profile("RECON-INV-COVE-V1","COMMERCIAL_INVOICE","COVE_ACK",HeaderFields());await f.Document("COMMERCIAL_INVOICE",HeaderValues());var changed=HeaderValues();changed[DocumentFieldCodes.TotalAmount]="4458.25";await f.Document("COVE_ACK",changed);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));Assert.Equal(ReconciliationOutcome.WITH_DIFFERENCES,result.Outcome);Assert.Equal(1,result.MismatchCount);var mismatch=Assert.Single(result.FieldResults,x=>x.Outcome==CrossValidationOutcome.MISMATCH);Assert.Equal(100m,mismatch.NumericDifference);}

  [Fact] public async Task Missing_field_is_insufficient_not_mismatch(){await using var f=await Fixture.Create();await f.Profile("RECON-INV-COVE-V1","COMMERCIAL_INVOICE","COVE_ACK",HeaderFields());await f.Document("COMMERCIAL_INVOICE",HeaderValues());var missing=HeaderValues();missing.Remove(DocumentFieldCodes.Incoterm);await f.Document("COVE_ACK",missing);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));Assert.Equal(ReconciliationOutcome.INSUFFICIENT_EVIDENCE,result.Outcome);Assert.Equal(0,result.MismatchCount);Assert.Equal(1,result.InsufficientEvidenceCount);Assert.Equal(CrossValidationOutcome.INSUFFICIENT_EVIDENCE,result.FieldResults.Single(x=>x.LeftFieldCode==DocumentFieldCodes.Incoterm).Outcome);}

  [Fact] public async Task Coverage_is_stable_13_of_14(){await using var f=await Fixture.Create();var fields=Enumerable.Range(1,14).Select(i=>PF(ReconciliationSection.OTHER,$"F{i}",$"F{i}",CrossComparisonType.NORMALIZED_TEXT)).ToList();await f.Profile("COVERAGE","COMMERCIAL_INVOICE","COVE_ACK",fields);var left=Enumerable.Range(1,14).ToDictionary(i=>$"F{i}",i=>$"V{i}");var right=Enumerable.Range(1,13).ToDictionary(i=>$"F{i}",i=>$"V{i}");await f.Document("COMMERCIAL_INVOICE",left);await f.Document("COVE_ACK",right);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));Assert.Equal(92.8571m,result.CoveragePercent);Assert.Equal(13,result.MatchCount);Assert.Equal(1,result.InsufficientEvidenceCount);}

  [Fact] public void Line_item_matcher_matches_two_items_and_does_not_fabricate_unmatched_pair(){var left=new[]{Item(1,"ABC-001",100,250),Item(2,"ABC-002",200,600),Item(3,"ABC-003",10,50)};var right=new[]{Item(1,"ABC-001",100,250),Item(2,"ABC-002",200,600)};var matches=new DocumentLineItemMatcher().Match(left,right);Assert.Equal(2,matches.Count(x=>x.Status==LineItemMatchStatus.MATCHED));Assert.Single(matches,x=>x.Status==LineItemMatchStatus.UNMATCHED_LEFT);Assert.DoesNotContain(matches,x=>x.Status==LineItemMatchStatus.AMBIGUOUS);}

  [Fact] public void Duplicate_deterministic_candidates_are_ambiguous_and_never_first(){var left=new[]{Item(1,"ABC-001",100,250)};var right=new[]{Item(1,"ABC-001",100,250),Item(2,"ABC-001",100,250)};var matches=new DocumentLineItemMatcher().Match(left,right);var ambiguous=Assert.Single(matches,x=>x.Status==LineItemMatchStatus.AMBIGUOUS);Assert.Null(ambiguous.RightLineItemId);Assert.Contains("múltiples partidas candidatas",ambiguous.Explanation);}

  [Fact] public async Task Line_item_value_difference_reuses_part_number_pair_and_rolls_up(){await using var f=await Fixture.Create();await f.Profile("LINES","COMMERCIAL_INVOICE","COVE_ACK",[Line(DocumentFieldCodes.Description,CrossComparisonType.NORMALIZED_TEXT),Line(DocumentFieldCodes.Quantity,CrossComparisonType.EXACT_NUMERIC),Line(DocumentFieldCodes.Unit,CrossComparisonType.NORMALIZED_IDENTIFIER),Line(DocumentFieldCodes.TotalAmount,CrossComparisonType.CURRENCY_AMOUNT)]);await f.Document("COMMERCIAL_INVOICE",[],items:[Item(1,"ABC-001",100,250),Item(2,"ABC-002",200,600)]);await f.Document("COVE_ACK",[],items:[Item(1,"ABC-001",100,250),Item(2,"ABC-002",200,610)]);var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));Assert.Equal(2,result.LineItemsMatched);Assert.Equal(ReconciliationOutcome.WITH_DIFFERENCES,result.Outcome);var mismatch=Assert.Single(result.FieldResults,x=>x.Outcome==CrossValidationOutcome.MISMATCH);Assert.Equal(10m,mismatch.NumericDifference);Assert.Equal(DocumentFieldCodes.TotalAmount,mismatch.LeftFieldCode);}

  [Fact] public async Task Multiple_invoices_pair_by_exact_document_reference(){await using var f=await Fixture.Create();await f.Profile("MULTI","COMMERCIAL_INVOICE","COVE_ACK",[PF(ReconciliationSection.IDENTIFICATION,DocumentFieldCodes.InvoiceNumber,DocumentFieldCodes.InvoiceNumber,CrossComparisonType.NORMALIZED_IDENTIFIER)]);await f.Document("COMMERCIAL_INVOICE",new(){[DocumentFieldCodes.InvoiceNumber]="INV-A"},references:["INV-A"]);await f.Document("COMMERCIAL_INVOICE",new(){[DocumentFieldCodes.InvoiceNumber]="INV-B"},references:["INV-B"]);await f.Document("COVE_ACK",new(){[DocumentFieldCodes.InvoiceNumber]="INV-B"},references:["INV-B"]);await f.Document("COVE_ACK",new(){[DocumentFieldCodes.InvoiceNumber]="INV-A"},references:["INV-A"]);var results=await f.Service.RunAsync(f.Operation.Id,f.User.Id);Assert.Equal(2,results.Count);Assert.All(results,x=>Assert.Equal(ReconciliationOutcome.MATCH,x.Outcome));Assert.All(results,x=>Assert.Equal(x.FieldResults[0].LeftNormalizedValue,x.FieldResults[0].RightNormalizedValue));}

  [Fact] public async Task Extracted_field_beats_existing_metadata_and_cross_result_is_reused(){await using var f=await Fixture.Create();var rule=new CrossValidationRule{Code="CROSS-REUSE",Version=1,Name="Reuse",SourceDocumentTypeCode="COMMERCIAL_INVOICE",TargetDocumentTypeCode="COVE_ACK",SourceFieldCode=DocumentFieldCodes.Quantity,TargetFieldCode=DocumentFieldCodes.Quantity,ComparisonType=CrossComparisonType.EXACT_NUMERIC};f.Db.Add(rule);await f.Db.SaveChangesAsync();var field=PF(ReconciliationSection.QUANTITIES,DocumentFieldCodes.Quantity,DocumentFieldCodes.Quantity,CrossComparisonType.EXACT_NUMERIC);field.CrossValidationRuleId=rule.Id;var profile=await f.Profile("REUSE","COMMERCIAL_INVOICE","COVE_ACK",[field]);var left=await f.Document("COMMERCIAL_INVOICE",new(){[DocumentFieldCodes.Quantity]="6500"});var right=await f.Document("COVE_ACK",new(){[DocumentFieldCodes.Quantity]="6500"});f.Db.DocumentFields.Add(new(){OperationDocumentId=right.Id,FieldCode=DocumentFieldCodes.Quantity,RawValue="6400",NormalizedValue="6400",ExtractionMethod=ExtractionMethod.EXISTING_METADATA,DataType=DocumentFieldDataType.QUANTITY});var extracted=right.Fields.Single(x=>x.ExtractionMethod==ExtractionMethod.PDF_TEXT);var cross=new CrossValidationResult{TradeOperationId=f.Operation.Id,CrossValidationRuleId=rule.Id,RuleCode=rule.Code,RuleVersion=1,SourceDocumentId=left.Id,TargetDocumentId=right.Id,SourceFieldId=left.Fields[0].Id,TargetFieldId=extracted.Id,SourceRawValue="6500",TargetRawValue="6500",SourceNormalizedValue="6500",TargetNormalizedValue="6500",Outcome=CrossValidationOutcome.MATCH,Explanation="Reused"};f.Db.Add(cross);await f.Db.SaveChangesAsync();var result=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));var detail=Assert.Single(result.FieldResults);Assert.Equal(cross.Id,detail.CrossValidationResultId);Assert.Equal("6500",detail.RightNormalizedValue);Assert.Equal(ExtractionMethod.PDF_TEXT,detail.RightExtractionMethod);Assert.Contains("reutilizado",detail.Explanation);Assert.Equal(profile.Id,result.ProfileId);}

  [Fact] public async Task History_is_immutable_and_reconciliation_never_creates_legal_result_finding_or_risk(){await using var f=await Fixture.Create();await f.Profile("HISTORY","COMMERCIAL_INVOICE","COVE_ACK",[PF(ReconciliationSection.VALUES,DocumentFieldCodes.TotalAmount,DocumentFieldCodes.TotalAmount,CrossComparisonType.CURRENCY_AMOUNT)]);var left=await f.Document("COMMERCIAL_INVOICE",new(){[DocumentFieldCodes.TotalAmount]="100"});await f.Document("COVE_ACK",new(){[DocumentFieldCodes.TotalAmount]="100"});var first=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));var snapshot=first.SnapshotJson;left.Fields[0].RawValue=left.Fields[0].NormalizedValue="110";await f.Db.SaveChangesAsync();var second=Assert.Single(await f.Service.RunAsync(f.Operation.Id,f.User.Id));Assert.Equal(ReconciliationOutcome.MATCH,first.Outcome);Assert.Equal(snapshot,(await f.Db.DocumentReconciliationResults.AsNoTracking().SingleAsync(x=>x.Id==first.Id)).SnapshotJson);Assert.Equal(ReconciliationOutcome.WITH_DIFFERENCES,second.Outcome);Assert.Equal(0,await f.Db.AuditResults.CountAsync());Assert.Equal(0,await f.Db.Findings.CountAsync());Assert.Equal(0,await f.Db.OperationRiskScores.CountAsync());}

  [Fact] public async Task Extractor_creates_two_line_items_idempotently_and_respects_no_text(){await using var f=await ExtractionFixture.Create();var text="ITEM 1\nPart: ABC-001\nDescription: GASKET A\nQuantity: 100\nUnit: PZA\nUnit Price: 2.50\nTotal: 250.00 USD\nITEM 2\nPart: ABC-002\nDescription: GASKET B\nQuantity: 200 PZA\nUnit Price: 3.00\nTotal: 600.00 USD";var doc=await f.Document(text);await f.Extractor.ExtractDocumentAsync(doc.Id,f.User.Id);await f.Extractor.ExtractDocumentAsync(doc.Id,f.User.Id);var items=await f.Db.DocumentLineItems.OrderBy(x=>x.Sequence).ToListAsync();Assert.Equal(2,items.Count);Assert.Equal("ABC-001",items[0].PartNumber);Assert.Equal(100,items[0].Quantity);Assert.Equal(250,items[0].TotalValue);var empty=await f.Document("");await f.Extractor.ExtractDocumentAsync(empty.Id,f.User.Id);Assert.False(await f.Db.DocumentLineItems.AnyAsync(x=>x.OperationDocumentId==empty.Id));}

  [Fact] public async Task Seed_is_idempotent_and_http_endpoints_are_authenticated_and_return_summary_detail(){using var factory=new SaceFactory();var anonymous=factory.CreateClient();Assert.Equal(System.Net.HttpStatusCode.Unauthorized,(await anonymous.GetAsync($"/api/operations/{Guid.NewGuid()}/reconciliations?page=1&pageSize=20")).StatusCode);await DbSeeder.SeedAsync(factory.Services);await DbSeeder.SeedAsync(factory.Services);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<SaceDbContext>();Assert.Equal(4,await db.DocumentReconciliationProfiles.CountAsync());Assert.Equal(4,await db.DocumentReconciliationProfiles.Select(x=>x.Code).Distinct().CountAsync());var op=await db.TradeOperations.FirstAsync();var invoice=await AddHttpDoc(db,op.Id,"COMMERCIAL_INVOICE","INV-HTTP");var cove=await AddHttpDoc(db,op.Id,"COVE_ACK","INV-HTTP");await db.SaveChangesAsync();var service=scope.ServiceProvider.GetRequiredService<IDocumentReconciliationService>();var run=await service.RunAsync(op.Id,Guid.Empty);var id=run.Single(x=>x.LeftDocumentId==invoice.Id&&x.RightDocumentId==cove.Id).Id;var client=await Client(factory);var summary=await Json(client.GetAsync($"/api/operations/{op.Id}/reconciliations?page=1&pageSize=20"));Assert.True(summary.RootElement.GetProperty("total").GetInt32()>0);var detail=await Json(client.GetAsync($"/api/operations/{op.Id}/reconciliations/{id}"));Assert.Equal(id,detail.RootElement.GetProperty("id").GetGuid());var lines=await Json(client.GetAsync($"/api/operations/{op.Id}/document-line-items?page=1&pageSize=50"));Assert.Equal(JsonValueKind.Array,lines.RootElement.GetProperty("items").ValueKind);}

  [Fact] public async Task Http_end_to_end_uploads_real_text_pdfs_extracts_fields_and_lines_and_reconciles(){using var factory=new SaceFactory();var client=await Client(factory);var created=await Json(client.PostAsJsonAsync("/api/operations",new{pedimentoNumber="26 48 1234 6888001",operationDate="2026-11-08T12:00:00Z",period="2026-11",operationType="Importacion",pedimentoKey="A1",tariffFraction="40169304",originCountry="US",destinationCountry="MX",customsRegime="Definitivo",isImmex=false,preferentialTreatment=false,tradeAgreement=(string?)null}));var operationId=created.RootElement.GetProperty("id").GetGuid();var invoice="Invoice: INV-E2E\nDate: 2026-10-01\nDescription: GASKET\nQuantity: 300 PZA\nTotal: 850.00 USD\nIncoterm: FOB\nITEM 1\nPart: ABC-001\nDescription: GASKET A\nQuantity: 100 PZA\nUnit Price: 2.50\nTotal: 250.00 USD\nITEM 2\nPart: ABC-002\nDescription: GASKET B\nQuantity: 200 PZA\nUnit Price: 3.00\nTotal: 600.00 USD";var cove=invoice.Replace("Invoice: INV-E2E","Reference: INV-E2E");await Upload(client,operationId,("invoice.pdf",TextPdf(invoice),"COMMERCIAL_INVOICE"),("cove.pdf",TextPdf(cove),"COVE_ACK"));var run=await Json(client.PostAsync($"/api/operations/{operationId}/reconciliations/run",null));Assert.True(run.RootElement.GetProperty("evaluated").GetInt32()>=1);var fields=await Json(client.GetAsync($"/api/operations/{operationId}/document-fields"));Assert.Equal(2,fields.RootElement.GetProperty("documentsProcessed").GetInt32());Assert.All(fields.RootElement.GetProperty("documents").EnumerateArray(),x=>Assert.Contains(x.GetProperty("fields").EnumerateArray(),f=>f.GetProperty("fieldCode").GetString()==DocumentFieldCodes.Quantity));var lines=await Json(client.GetAsync($"/api/operations/{operationId}/document-line-items?page=1&pageSize=50"));Assert.Equal(4,lines.RootElement.GetProperty("total").GetInt32());var summary=await Json(client.GetAsync($"/api/operations/{operationId}/reconciliations?page=1&pageSize=20"));var recon=summary.RootElement.GetProperty("items").EnumerateArray().First(x=>x.GetProperty("profileCode").GetString()=="RECON-INV-COVE-V1");Assert.Equal("MATCH",recon.GetProperty("outcome").GetString());Assert.Equal(2,recon.GetProperty("lineItemsMatched").GetInt32());var detail=await Json(client.GetAsync($"/api/operations/{operationId}/reconciliations/{recon.GetProperty("id").GetGuid()}"));Assert.Contains(detail.RootElement.GetProperty("fields").EnumerateArray(),x=>x.GetProperty("ruleCode").GetString()=="CROSS-INV-COVE-VALUE-001");Assert.Equal(2,detail.RootElement.GetProperty("lineItems").EnumerateArray().Count(x=>x.GetProperty("status").GetString()=="MATCHED"));}

  [Fact]
  public async Task Http_end_to_end_single_value_difference_is_exactly_one_mismatch_and_never_a_legal_finding(){
    using var factory=new SaceFactory();
    var client=await Client(factory);
    var created=await Json(client.PostAsJsonAsync("/api/operations",new{pedimentoNumber="26 48 1234 6888002",operationDate="2026-11-08T12:00:00Z",period="2026-11",operationType="Importacion",pedimentoKey="A1",tariffFraction="40169304",originCountry="US",destinationCountry="MX",customsRegime="Definitivo",isImmex=false,preferentialTreatment=false,tradeAgreement=(string?)null}));
    var operationId=created.RootElement.GetProperty("id").GetGuid();
    var invoice="Invoice: INV-DIFF\nDate: 2026-10-01\nDescription: GASKET\nQuantity: 300 PZA\nTotal: 850.00 USD\nIncoterm: FOB\nITEM 1\nPart: ABC-001\nDescription: GASKET A\nQuantity: 100 PZA\nUnit Price: 2.50\nTotal: 250.00 USD\nITEM 2\nPart: ABC-002\nDescription: GASKET B\nQuantity: 200 PZA\nUnit Price: 3.00\nTotal: 600.00 USD";
    var cove=invoice.Replace("Invoice: INV-DIFF","Reference: INV-DIFF").Replace("Total: 850.00 USD","Total: 950.00 USD");
    await Upload(client,operationId,("invoice-diff.pdf",TextPdf(invoice),"COMMERCIAL_INVOICE"),("cove-diff.pdf",TextPdf(cove),"COVE_ACK"));

    var reextract=await client.PostAsync($"/api/operations/{operationId}/document-fields/reextract",null);
    reextract.EnsureSuccessStatusCode();
    var beforeOperation=await Json(client.GetAsync($"/api/operations/{operationId}"));
    var findingsBefore=beforeOperation.RootElement.GetProperty("findings").EnumerateArray().Select(x=>x.GetProperty("id").GetGuid()).Order().ToArray();
    var run=await client.PostAsync($"/api/operations/{operationId}/reconciliations/run",null);
    run.EnsureSuccessStatusCode();

    var summary=await Json(client.GetAsync($"/api/operations/{operationId}/reconciliations?page=1&pageSize=20"));
    var reconciliation=summary.RootElement.GetProperty("items").EnumerateArray().First(x=>x.GetProperty("profileCode").GetString()=="RECON-INV-COVE-V1");
    Assert.Equal("WITH_DIFFERENCES",reconciliation.GetProperty("outcome").GetString());
    Assert.Equal(1,reconciliation.GetProperty("mismatchCount").GetInt32());
    var detail=await Json(client.GetAsync($"/api/operations/{operationId}/reconciliations/{reconciliation.GetProperty("id").GetGuid()}"));
    var mismatch=Assert.Single(detail.RootElement.GetProperty("fields").EnumerateArray(),x=>x.GetProperty("outcome").GetString()=="MISMATCH");
    Assert.Equal(DocumentFieldCodes.TotalAmount,mismatch.GetProperty("leftFieldCode").GetString());
    Assert.Equal(100m,mismatch.GetProperty("numericDifference").GetDecimal());
    var operation=await Json(client.GetAsync($"/api/operations/{operationId}"));
    var findingsAfter=operation.RootElement.GetProperty("findings").EnumerateArray().ToArray();
    Assert.Equal(findingsBefore,findingsAfter.Select(x=>x.GetProperty("id").GetGuid()).Order().ToArray());
    Assert.DoesNotContain(findingsAfter,x=>(x.GetProperty("ruleId").GetString()??"").StartsWith("LEGAL",StringComparison.OrdinalIgnoreCase));
  }

  [Fact]
  public async Task Migration_is_fresh_incremental_and_down_scoped(){
    const string previous="20261104182117_CrossValidationExtractionCorrectionV1";
    var dir=Path.Combine(Path.GetTempPath(),$"sace-recon-{Guid.NewGuid():N}");
    Directory.CreateDirectory(dir);
    var path=Path.Combine(dir,"test.db");
    try{
      await using(var db=Context(path)){
        var migrator=db.Database.GetService<IMigrator>();
        await migrator.MigrateAsync(previous);
        Assert.False(await Table(db,"DocumentReconciliationProfiles"));

        var userId=Guid.NewGuid();var operationId=Guid.NewGuid();var documentTypeId=Guid.NewGuid();var documentId=Guid.NewGuid();var fieldId=Guid.NewGuid();var now=new DateTime(2026,11,8,0,0,0,DateTimeKind.Utc);
        await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO Users (Id,Name,Email,PasswordHash,Role,IsActive,CreatedAt) VALUES ({userId},{"Migration user"},{$"migration-{Guid.NewGuid():N}@example.invalid"},{"synthetic"},{"Administrator"},{true},{now})");
        await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO TradeOperations (Id,Folio,PedimentoNumber,OperationType,Period,OperationDate,PedimentoKey,TariffFraction,OriginCountry,DestinationCountry,CustomsRegime,IsImmex,PreferentialTreatment,Status,CreatedAt,UpdatedAt) VALUES ({operationId},{"KEEP-RECON"},{"26-KEEP"},{"Importacion"},{"2026-11"},{now},{"A1"},{"40169304"},{"US"},{"MX"},{"Definitivo"},{false},{false},{"PendingAudit"},{now},{now})");
        await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO DocumentTypes (Id,Code,Name,Description,CorrectionResponsible,IsActive) VALUES ({documentTypeId},{"KEEP_RECON_DOC"},{"Keep"},{"Synthetic migration fixture"},{"Operations"},{true})");
        await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO OperationDocuments (Id,TradeOperationId,DocumentTypeId,OriginalFileName,StoredFileName,MimeType,Extension,FileSize,FilePath,Version,ValidationStatus,UploadedAt,UploadedBy) VALUES ({documentId},{operationId},{documentTypeId},{"keep.pdf"},{"keep.pdf"},{"application/pdf"},{".pdf"},{1L},{"synthetic/keep.pdf"},{1},{"Valid"},{now},{userId})");
        await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO DocumentFields (Id,OperationDocumentId,FieldCode,RawValue,NormalizedValue,DataType,Unit,Currency,Confidence,ExtractionMethod,SourceLocator,GroupKey,Sequence,IsManuallyConfirmed,CreatedAt,UpdatedAt) VALUES ({fieldId},{documentId},{DocumentFieldCodes.InvoiceNumber},{"INV-KEEP"},{"INV-KEEP"},{"IDENTIFIER"},{(string?)null},{(string?)null},{(double?)null},{"PDF_TEXT"},{(string?)null},{(string?)null},{(int?)null},{false},{now},{now})");

        await migrator.MigrateAsync();
        Assert.True(await Table(db,"DocumentReconciliationProfiles"));
        Assert.True(await Table(db,"DocumentLineItems"));
        Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM TradeOperations WHERE Folio='KEEP-RECON'"));
        Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM OperationDocuments WHERE OriginalFileName='keep.pdf'"));
        Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM DocumentFields WHERE NormalizedValue='INV-KEEP'"));

        await migrator.MigrateAsync(previous);
        Assert.False(await Table(db,"DocumentReconciliationProfiles"));
        Assert.False(await Table(db,"DocumentLineItems"));
        Assert.True(await Table(db,"CrossValidationResults"));
        Assert.True(await Table(db,"AuditResults"));
        Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM TradeOperations WHERE Folio='KEEP-RECON'"));
        Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM OperationDocuments WHERE OriginalFileName='keep.pdf'"));
        Assert.Equal(1,await Scalar(db,"SELECT COUNT(*) FROM DocumentFields WHERE NormalizedValue='INV-KEEP'"));
      }
      await using(var fresh=Context(Path.Combine(dir,"fresh.db"))){
        await fresh.Database.MigrateAsync();
        Assert.True(await Table(fresh,"DocumentReconciliationResults"));
        Assert.True(await Table(fresh,"DocumentLineItemMatches"));
      }
    }finally{
      SqliteConnection.ClearAllPools();
      if(Directory.Exists(dir)&&Path.GetFullPath(dir).StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase))Directory.Delete(dir,true);
    }
  }

  private static Dictionary<string,string> HeaderValues()=>new(){{DocumentFieldCodes.InvoiceNumber,"INV-001"},{DocumentFieldCodes.Date,"2026-10-01"},{DocumentFieldCodes.Description,"GASKET"},{DocumentFieldCodes.Quantity,"6500"},{DocumentFieldCodes.Unit,"PZA"},{DocumentFieldCodes.TotalAmount,"4358.25"},{DocumentFieldCodes.Currency,"USD"},{DocumentFieldCodes.Incoterm,"FOB"}};
  private static List<DocumentReconciliationProfileField> HeaderFields()=>[PF(ReconciliationSection.IDENTIFICATION,DocumentFieldCodes.InvoiceNumber,DocumentFieldCodes.InvoiceNumber,CrossComparisonType.NORMALIZED_IDENTIFIER),PF(ReconciliationSection.DATES,DocumentFieldCodes.Date,DocumentFieldCodes.Date,CrossComparisonType.DATE),PF(ReconciliationSection.MERCHANDISE,DocumentFieldCodes.Description,DocumentFieldCodes.Description,CrossComparisonType.NORMALIZED_TEXT),PF(ReconciliationSection.QUANTITIES,DocumentFieldCodes.Quantity,DocumentFieldCodes.Quantity,CrossComparisonType.EXACT_NUMERIC),PF(ReconciliationSection.QUANTITIES,DocumentFieldCodes.Unit,DocumentFieldCodes.Unit,CrossComparisonType.NORMALIZED_IDENTIFIER),PF(ReconciliationSection.VALUES,DocumentFieldCodes.TotalAmount,DocumentFieldCodes.TotalAmount,CrossComparisonType.CURRENCY_AMOUNT),PF(ReconciliationSection.VALUES,DocumentFieldCodes.Currency,DocumentFieldCodes.Currency,CrossComparisonType.NORMALIZED_IDENTIFIER),PF(ReconciliationSection.COMMERCIAL_TERMS,DocumentFieldCodes.Incoterm,DocumentFieldCodes.Incoterm,CrossComparisonType.NORMALIZED_IDENTIFIER)];
  private static DocumentReconciliationProfileField PF(ReconciliationSection section,string left,string right,CrossComparisonType type)=>new(){Section=section,LeftFieldCode=left,RightFieldCode=right,ComparisonType=type,RequiredForCoverage=true,LineItemScope=LineItemScope.HEADER,IsActive=true};
  private static DocumentReconciliationProfileField Line(string field,CrossComparisonType type)=>new(){Section=ReconciliationSection.LINE_ITEMS,LeftFieldCode=field,RightFieldCode=field,ComparisonType=type,RequiredForCoverage=true,LineItemScope=LineItemScope.LINE_ITEM,IsActive=true};
